                        //     statement = statement + "$" + z_id_ref + " isa knowledge_model, has name \"" + model_name + "\", has nrid \"" + node.z + "\";\n"
                        //     statement = statement + "$" + z_id_ref + " (km_entity: $" + node_id_ref + ");\n\n"
                        //     typeql_schema_dict["kg_entity"] += statement
                        // }

                        let role_map = {}
