                        statement = "match\n$" + node_id_ref + " isa km_relation, has nrid \"" + node.id + "\";\n"
                        statement = statement + "$" + z_id_ref + " isa knowledge_model, has nrid \"" + node.z + "\";\n"
                        statement = statement + "insert\n"
                        statement = statement + "$" + z_id_ref + " (km_relation: $" + node_id_ref + ");\n\n"
                        typeql_schema_dict["kg_relation"] += statement
                        // } 
                        // else {
                        //     kg_ = { ...kg_, [node.z]: true }
                        //     parent = RED.nodes.subflow(node.z) ? RED.nodes.subflow(node.z) : RED.nodes.workspace(node.z)
                        //     model_name = parent.name ? parent.name : parent.label
                        //     statement = "match\n$" + node_id_ref + " isa km_relation, has nrid \"" + node.id + "\";\n"
                        //     statement = statement + "insert\n"
                        //     statement = statement + "$" + z_id_ref + " isa knowledge_model, has name \"" + model_name + "\", has nrid \"" + node.z + "\";\n"
                        //     statement = statement + "$" + z_id_ref + " (km_relation: $" + node_id_ref + ");\n\n"
                        //     typeql_schema_dict["kg_relation"] += statement
                        // }

