    /**
     * Creates a deployment instance in causeway repo which stores previous state and other info related to the model. Implements for both causal model and knowledge models 
     * @param {*} active_workspace
     */
    async function deploymentInstance(active_workspace, model_type) {
        let activeproject = RED.projects.getActiveProject() !== undefined ? RED.projects.getActiveProject() : RED.nodes.workspace(active_workspace)

        let name = activeproject.name !== undefined ? activeproject.name : activeproject.label
        let version = activeproject.version !== undefined ? activeproject.version : activeproject.id
        let nrid = name + ":" + version
        let project_stmt = "$project isa project, has nrid \"" + nrid + "\", has name \"" + name + "\"" + ", has id " + "\"" + version + "\";\n"


        await $.ajax({
            headers: {
                Accept: "text/html",
                // "Accept-Language": lang,
            },
            cache: false,
            url: "typedb/causewayRepo",
            type: "POST",
            data: {
                server: window.location.hostname + ":1729",
                activeproject: project_stmt,
                schema: JSON.stringify(data_schema_typeql),
                query: "$" + model_type + " isa " + model_type + "," + " has nrid \"" + active_workspace + "\";\n",
                model_type: model_type
            },
            success: async function (res) {
                console.log(res)
            },
        }).fail(function (xhr, status, error) {
            console.log("xhr: ", xhr);
            console.log(xhr.responseJSON.code)
            console.log(xhr.responseJSON.message)
            console.log("status: ", status);
            console.log("error: ", error);
            RED.notify("[TypeDB] " + xhr.responseJSON.message, "error");
        }).done(() => {
            return
        })
    }
