    /**
     *  Helper function to generate knowledge model schema using geminos schema
     * @param {*} active_workspace - current flow
     * @param {*} attr_map - map to knowledge model attributes
     * @param {*} gem_attr_map - map to knowledge model schema attributes
     * @returns 
     */
    async function generateFullSchema(active_workspace, attr_map, gem_attr_map) {
        // console.log("attr")
        // for (var attribute in attr_map) {
        //     await addAttribute(attribute)
        // }

        // ATTRIBUTES
        // console.log("Gem attribute map: " , gem_attr_map)
        let defined_properties = {}
        let defined_attribute = {}
        let defined_attribute_type = {}
        let node = ""
        let z_id_ref = ""
        let key = ""
        Object.keys(gem_attr_map).forEach(attribute => {
            //METHOD 1 

            // 1.1] ADD ATTRIBUTES
            statement = "insert\n"
            statement = statement + "$attribute isa km_attribute, has name \"" + attribute + "\";\n"
            typeql_schema_dict["km_attribute"] += statement

            console.log(statement)

            gem_attr_map[attribute].forEach(instance => {
                let node_id_ref = instance["id"].split(".").join("")
                // // connect attribute_instance to entity
                var statement = "match\n"
                statement = statement + "$" + node_id_ref + " isa " + instance["type"] + ", has nrid \"" + instance["id"] + "\";\n";
                statement = statement + "$attribute isa km_attribute, has name \"" + attribute + "\";\n"
                // console.log(statement)
                if (defined_properties[instance["id"]]) {
                    statement = statement + "$props_" + node_id_ref + " isa properties, has nrid \"props_" + instance["id"] + "\";\n";
                    statement += "insert\n";
                    statement = statement + "$props_" + node_id_ref + " (modified: $" + node_id_ref + ", modifier:$attribute);\n\n"

                } else {
                    statement += "insert\n";
                    statement = statement + "$props_" + node_id_ref + " isa properties, has nrid \"props_" + instance["id"] + "\";\n";
                    statement = statement + "$props_" + node_id_ref + " (modified: $" + node_id_ref + ", modifier:$attribute);\n"
                    defined_properties = { ...defined_properties, [instance["id"]]: true }
                }
                typeql_schema_dict["properties"] += statement
                // console.log(statement)

                node = RED.nodes.node(instance["id"])
                z_id_ref = (node.z).split(".").join("")
                if (!defined_attribute_type[attribute]) {
                    statement = "match\n"
                    statement = statement + "$" + z_id_ref + " isa knowledge_model, has nrid \"" + node.z + "\";\n"
                    statement = statement + "$" + attribute + " isa km_attribute, has name \"" + attribute + "\";\n";
                    statement += "insert\n"
                    statement = statement + "$" + z_id_ref + " (km_attribute: $" + attribute + ");\n\n";
                    typeql_schema_dict["km_attribute"] += statement
                    defined_attribute_type = { ...defined_attribute_type, [attribute]: true }
                }
            })
        })

        // generate entity, relation, and rule typeql schema
        added_define = false
        for (var type in typeql_schema_dict) {
            if (typeql_schema_dict[type] !== "") {
                typeql += typeql_headers[type]
                typeql += typeql_schema_dict[type]
                typeql += newline
            }
        }
        return typeql
    }


