    /**
     * Request function for injecting geminos schema for causal and knowledge model instances 
     * @param {string} database - string containing the name of the database which is needed for TypeDB api
     * @param {string} type - indicates whether to route to causal api or knowledge api 
     * @returns {} - no returns
     */
    async function deployModelSchema(database, type, model_schema) {
        let req_data = {}
        let req_url = "typedb/"
        if (type === "knowledge") {
            req_data = {
                server: "127.0.0.1:1729",
                database: database,
                session_type: "SCHEMA",
                transaction_type: "WRITE",
                schema: model_schema
            }
            req_url += type
        }
        if (type === "causal") {
            req_data = {
                server: "127.0.0.1:1729",
                database: database,
                dbtype: ""
            }
            req_url += type
        }

        await $.ajax({
            headers: {
                Accept: "text/html"
            },
            cache: false,
            type: "POST",
            url: req_url,
            data: req_data,
            success: async function (res) {
            },
            error: async function (res) {
                console.log(error)
                console.log(RED.notify)
                RED.notify("[TypeDB] Error: " + error.responseText, { type: "error", timeout: 10000 })
            }
        }).done(result => {
            RED.notify("[TypeDB] " + result, "success")
            console.log("result: ", result)
        });
    }

